function quant(pixels, n){
  var buckets = {};
  for (var i = 0; i < pixels.length; i++){
    var p = pixels[i];
    var r = (p[0] >> 4) << 4, g = (p[1] >> 4) << 4, b = (p[2] >> 4) << 4;
    var key = r + "," + g + "," + b;
    buckets[key] = (buckets[key] || 0) + 1;
  }
  var arr = [];
  for (var k in buckets) arr.push({ color: k, count: buckets[k] });
  arr.sort(function(a, b){ return b.count - a.count; });
  return arr.slice(0, n).map(function(x){
    return "#" + x.color.split(",").map(function(v){ var h = parseInt(v).toString(16); return h.length < 2 ? "0" + h : h; }).join("");
  });
}
var EXPORTS = { quant: quant };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.ImagePaletteForgePure = EXPORTS; }
